edits.newText:
class VoidBrowserController {
  Future<void> Function(String path)? _scrollToTrack;
  bool Function(String path)? _isTrackInView;

  /// Centre the row for [path] in view; no-op when the browser is unmounted.
  Future<void> scrollToTrack(String path) async =>
      await _scrollToTrack?.call(path);

  /// Returns whether [path]'s row is currently built inside the visible
  /// viewport.
  ///
  /// When the browser is unmounted (or before its first layout), this
  /// pessimistically reports `true` to avoid exposing an action before we can
  /// reliably measure.
  bool isTrackInView(String path) => _isTrackInView?.call(path) ?? true;
}

